mapper.select:
SELECT
  (
    SELECT COUNT(*)
    FROM tl_documents d
    WHERE d.uploader_user_id = #{userId}

      AND d.meeting_id = #{meetingId}


      AND d.doc_id = #{docId}

  )
  +
  (
    SELECT COUNT(*)
    FROM tl_documents d
    JOIN tl_trans_docs t
      ON t.original_doc_id = d.doc_id
    WHERE d.uploader_user_id = #{userId}

      AND d.meeting_id = #{meetingId}


      AND d.doc_id = #{docId}


      AND t.target_language = #{targetLang}


      AND t.provider = #{provider}

  ) AS total

SELECT * FROM ( /* ---- 원문 행: 번역 컬럼은 NULL, 항상 1행 보장 ---- */ SELECT d.doc_id, d.uploader_user_id, d.meeting_id, d.original_name, d.filepath, d.mime_type, d.size AS doc_size, d.sha256 AS doc_sha256, d.original_lang,
NULL AS trans_doc_id, NULL AS original_doc_id, NULL AS target_language, NULL AS translated_rel_path, NULL AS request_id, NULL AS provider, NULL AS size_bytes, NULL AS checksum_sha256, NULL AS translated_at,
'original' AS row_type, 0 AS sort_ord FROM tl_documents d WHERE d.uploader_user_id = #{userId}
AND d.meeting_id = #{meetingId}
AND d.doc_id = #{docId}
UNION ALL
/* ---- 번역 행: 선택 필터 적용 ---- */ SELECT d.doc_id, d.uploader_user_id, d.meeting_id, d.original_name, d.filepath, d.mime_type, d.size AS doc_size, d.sha256 AS doc_sha256, d.original_lang,
t.trans_doc_id, t.original_doc_id, t.target_language, t.translated_rel_path, t.request_id, t.provider, t.size_bytes, t.checksum_sha256, t.translated_at,
'translation' AS row_type, 1 AS sort_ord FROM tl_documents d JOIN tl_trans_docs t ON t.original_doc_id = d.doc_id WHERE d.uploader_user_id = #{userId}
AND d.meeting_id = #{meetingId}
AND d.doc_id = #{docId}
AND t.target_language = #{targetLang}
AND t.provider = #{provider}
) x ORDER BY x.doc_id DESC, x.sort_ord ASC, /* 원문 먼저, 번역 다음 */ x.translated_at DESC, x.trans_doc_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(DISTINCT d.doc_id)
FROM tl_documents d
WHERE d.uploader_user_id = #{userId}

  AND d.meeting_id = #{meetingId}


  AND d.doc_id = #{docId}

SELECT

FROM tl_documents d
WHERE d.uploader_user_id = #{userId}

  AND d.meeting_id = #{meetingId}


  AND d.doc_id = #{docId}

ORDER BY d.doc_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT

FROM tl_trans_docs t
JOIN tl_documents d
  ON d.doc_id = t.original_doc_id
 AND d.uploader_user_id = #{userId}
WHERE t.original_doc_id IN

    #{id}


  AND t.target_language = #{targetLang}


  AND t.provider = #{provider}

ORDER BY t.original_doc_id DESC,
         t.translated_at DESC,
         t.trans_doc_id DESC
